 static class Drain{MediaCodec codec;MediaMuxer mux;boolean started;int track=-1;MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();void take(boolean end,AtomicBoolean stop)throws Exception{long deadline=System.nanoTime()+30_000_000_000L;while(true){AudioEngine.check(stop);int ix=codec.dequeueOutputBuffer(info,end?10000:0);if(ix==MediaCodec.INFO_TRY_AGAIN_LATER){if(!end)return;if(System.nanoTime()>deadline)throw new IOException("Encoder stopped responding at finalization.");continue;}if(ix==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){track=mux.addTrack(codec.getOutputFormat());mux.start();started=true;}else if(ix>=0){ByteBuffer b=codec.getOutputBuffer(ix);if((info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)!=0)info.size=0;if(info.size>0){if(!started)throw new IOException("Video samples arrived before format.");b.position(info.offset);b.limit(info.offset+info.size);mux.writeSampleData(track,b,info);}boolean done=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;codec.releaseOutputBuffer(ix,false);if(done)return;}}}}
 public static File encodeVideo(Context c,Project p,File target,int w,int h,boolean quality,AtomicBoolean stop,Progress progress)throws Exception{ATSModel m=p.model;MediaCodec codec=MediaCodec.createByCodecName(encoder(w,h,m.fps));MediaMuxer mux=null;Surface input=null;GL gl=null;Bitmap frame=null;Compositor comp=new Compositor(c,m,p.media);comp.fit=p.fit;comp.dates=p.overrides.optBoolean("dates",true);comp.circles=p.overrides.optBoolean("circles",true);Drain d=new Drain();try{boolean rotate=!codec.getCodecInfo().getCapabilitiesForType("video/avc").getVideoCapabilities().areSizeAndRateSupported(w,h,m.fps);int ew=rotate?h:w,eh=rotate?w:h;MediaFormat f=MediaFormat.createVideoFormat("video/avc",ew,eh);f.setInteger(MediaFormat.KEY_COLOR_FORMAT,MediaCodecInfo.CodecCapabilities.COLOR_FormatSurface);f.setInteger(MediaFormat.KEY_BIT_RATE,Math.max(1000000,Math.min(50000000,(int)(w*(long)h*m.fps*(quality?.16:.105)))));f.setInteger(MediaFormat.KEY_FRAME_RATE,m.fps);f.setInteger(MediaFormat.KEY_I_FRAME_INTERVAL,2);codec.configure(f,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);input=codec.createInputSurface();codec.start();mux=new MediaMuxer(target.getPath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);if(rotate)mux.setOrientationHint(90);d.codec=codec;d.mux=mux;gl=new GL(input);frame=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);for(int i=0;i<m.totalFrames;i++){AudioEngine.check(stop);d.take(false,stop);comp.render(frame,i);gl.frame(frame,i*1000000000L/m.fps,ew,eh,rotate);if(i%Math.max(1,m.fps/5)==0)progress.update("Rendering MP4",10+(int)(i*80L/m.totalFrames));}codec.signalEndOfInputStream();d.take(true,stop);return target;}finally{comp.close();if(frame!=null)frame.recycle();if(gl!=null)gl.close();if(input!=null)input.release();try{codec.stop();}catch(Exception ignored){}codec.release();if(mux!=null){if(d.started)try{mux.stop();}catch(Exception ignored){}mux.release();}}}
 static int find(MediaExtractor e,String mime)throws IOException{for(int i=0;i<e.getTrackCount();i++)if(e.getTrackFormat(i).getString(MediaFormat.KEY_MIME).startsWith(mime))return i;throw new IOException("Missing "+mime+" track.");}
 static void mux(File video,File audio,File output,AtomicBoolean stop)throws Exception{MediaExtractor v=new MediaExtractor(),a=new MediaExtractor();MediaMuxer mux=null;boolean started=false;try{v.setDataSource(video.getPath());a.setDataSource(audio.getPath());int vi=find(v,"video/"),ai=find(a,"audio/");v.selectTrack(vi);a.selectTrack(ai);mux=new MediaMuxer(output.getPath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);MediaFormat vf=v.getTrackFormat(vi);if(vf.containsKey(MediaFormat.KEY_ROTATION))mux.setOrientationHint(vf.getInteger(MediaFormat.KEY_ROTATION));int vt=mux.addTrack(vf),at=mux.addTrack(a.getTrackFormat(ai));mux.start();started=true;ByteBuffer buffer=ByteBuffer.allocateDirect(8*1024*1024);MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();while(v.getSampleTime()>=0||a.getSampleTime()>=0){AudioEngine.check(stop);boolean use=a.getSampleTime()<0||v.getSampleTime()>=0&&v.getSampleTime()<=a.getSampleTime();MediaExtractor e=use?v:a;buffer.clear();int n=e.readSampleData(buffer,0);if(n<0)break;info.set(0,n,e.getSampleTime(),e.getSampleFlags());mux.writeSampleData(use?vt:at,buffer,info);e.advance();}}finally{v.release();a.release();if(mux!=null){if(started)try{mux.stop();}catch(Exception ignored){}mux.release();}}}
 public static File export(Context c,Project p,File job,int w,int h,boolean quality,AtomicBoolean stop,Progress progress)throws Exception{long start=System.currentTimeMillis();File wav=AudioEngine.mix(c,p,job,stop,(phase,x)->progress.update(phase,(int)(x*7)));progress.update("Encoding AAC audio",8);File audio=AudioEngine.encodeAAC(wav,new File(job,"audio.m4a"),stop);File video=encodeVideo(c,p,new File(job,"video.mp4"),w,h,quality,stop,progress);progress.update("Finalizing MP4",92);File output=new File(job,"final.mp4");mux(video,audio,output,stop);MediaExtractor verified=new MediaExtractor();try{verified.setDataSource(output.getPath());find(verified,"video/");find(verified,"audio/");}finally{verified.release();}JSONObject report=new JSONObject().put("product","ATS Android 3.0.2-A1").put("width",w).put("height",h).put("fps",p.model.fps).put("frames",p.model.totalFrames).put("duration",p.model.totalFrames/(double)p.model.fps).put("elapsed_seconds",(System.currentTimeMillis()-start)/1000.0).put("codec","H.264 + AAC").put("notices",new JSONArray(p.model.notices));JSONArray scenes=new JSONArray();for(ATSModel.Scene s:p.model.scenes)scenes.put(new JSONObject().put("id",s.id).put("motion",s.motion).put("transition",s.transition).put("transition_frames",s.transitionFrames));report.put("scenes",scenes);report.put("contract_id",SyncSupport.CONTRACT).put("utilization",SyncUsage.utilization(p.model,p.music!=null));try(FileOutputStream out=new FileOutputStream(new File(c.getFilesDir(),"last-export.report.json"))){out.write(report.toString(2).getBytes("UTF-8"));}progress.update("Saving video",97);return output;}
